     * Reply routing adopts the source conversation's active channel so future replies go to where the
     * contact last reached us.
     *
     * Scopes: conversations:update.
     *
     * @param  string  $sourceConversationId  ID of the conversation to merge in and delete
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/merge_conversation_api_v1_conversations__conversation_id__merge_post
     */
    public function merge(string $conversationId, string $sourceConversationId, ?string $idempotencyKey = null): Conversation
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/conversations/'.Payload::segment($conversationId).'/merge',
            body: Payload::body(['source_conversation_id' => $sourceConversationId]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return Conversation::fromArray($response->data());
    }

    /**
     * Get Previous Conversations.
     *
     * Summarize a contact's previous conversations + advertise the merge target.
     *
     * Redesigned (June 2026) to power a single-line history summary plus the reopen-&-merge
     * affordance, instead of a list of heavy per-conversation cards. Returns CHEAP aggregates over the
     * SAME contact's prior conversations (excluding the current one):
     *
     * * total_previous — COUNT of prior conversations * distinct_channel_count — COUNT(DISTINCT
     * channel_id) * latest_previous_at — MAX(last_message_at) * merge_target_conversation_id — the
     * ONLY conversation this one may be merged into: the contact's OVERALL most-recent prior
     * conversation, and ONLY when that immediately-previous conversation is on the SAME channel
     * (channel_id) as the current one. Null when the immediately-previous conversation overall is on a
     * different channel (even if an older same-channel prior exists). Computed by the SAME server-side
     * helper the POST /{id}/merge endpoint enforces with, so the FE can never advertise a target the
     * backend would reject. * mergeable — merge_target_conversation_id is not None
     *
     * Scopes: conversations:read.
     *
     * @param  ?int  $limit  Deprecated/ignored — items[] is no longer populated
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/get_previous_conversations_api_v1_conversations__conversation_id__previous_get
     */
    public function getPrevious(string $conversationId, ?int $limit = null): PreviousConversations
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/conversations/'.Payload::segment($conversationId).'/previous',
            query: Payload::query(['limit' => $limit]),
        ));

        return PreviousConversations::fromArray($response->data());
    }

    /**
