    }

    /**
     * Get Conversation Sender Options.
     *
     * List email senders the caller may use for replying to this conversation.
     *
     * Returns the user's accessible support-capable email connections, plus an ACL-override entry when
     * the conversation's default reply sender (the receiving connection's outbound_provider) is NOT
     * already in that set. The client pre-selects default_option_id and POSTs the chosen value as
     * MessageCreate.sender_id on the outbound send. The server re-validates the choice on the send
     * path.
     *
     * Returns {"options": [], "default_option_id": null, "default_reply_sender_id": null} for
     * non-email conversations so clients can rely on a stable response shape.
     *
     * Scopes: conversations:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/get_conversation_sender_options_api_v1_conversations__conversation_id__sender_options_get
     */
    public function getSenderOptions(string $conversationId): SenderOptions
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/conversations/'.Payload::segment($conversationId).'/sender-options',
        ));

        return SenderOptions::fromArray($response->data());
    }

    /**
     * Unsnooze Conversation.
     *
     * Clear a conversation's snooze (return it to the Open tab).
     *
     * Sets snoozed_until and snooze_reopen_on_message back to NULL. Status is untouched. Idempotent
     * — unsnoozing an already-unsnoozed conversation succeeds and still emits conversation.updated
     * so stale client state converges.
     *
     * Cross-agent rules (when allow_messaging_other_agents_conversations is False): only ADMIN/OWNER
     * may unsnooze a conversation assigned to another agent.
     *
     * Scopes: conversations:update.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/unsnooze_conversation_api_v1_conversations__conversation_id__snooze_delete
     */
    public function unsnooze(string $conversationId): Conversation
    {
        $response = $this->connector->send(new Request(
            Method::Delete,
            '/conversations/'.Payload::segment($conversationId).'/snooze',
        ));

        return Conversation::fromArray($response->data());
    }

    /**
     * Snooze Conversation.
     *
     * Snooze (postpone) a conversation.
     *
     * Snooze is a DERIVED state: the conversation status stays open / assigned — it simply drops off
     * the Open tab and appears on the Snoozed tab until snoozed_until passes (query-time expiry, no
     * background job). Once the timestamp passes it behaves like a normal open conversation again.
     *
     * Body: - snoozed_until: timezone-aware ISO datetime; MUST be in the future. - reopen_on_message:
     * when true the inbound-message worker clears the snooze (returns it to Open) when a customer
     * message arrives.
     *
     * Scopes: conversations:update.
     *
     * @param  DateTimeInterface|string  $snoozedUntil  Timezone-aware ISO datetime when the snooze should expire. Must be in the future. After this moment the conversation behaves as a normal open conversation again.
     * @param  ?bool  $reopenOnMessage  When true, an inbound customer message arriving while the conversation is snoozed clears the snooze and returns it to the Open tab (handled by the inbound-message worker).
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/snooze_conversation_api_v1_conversations__conversation_id__snooze_post
     */
    public function snooze(string $conversationId, DateTimeInterface|string $snoozedUntil, ?bool $reopenOnMessage = null, ?string $idempotencyKey = null): Conversation
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/conversations/'.Payload::segment($conversationId).'/snooze',
            body: Payload::body(['snoozed_until' => $snoozedUntil, 'reopen_on_message' => $reopenOnMessage]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return Conversation::fromArray($response->data());
    }

    /**
     * Summarize Conversation.
     *
     * Manually trigger AI summary generation for a conversation.
     *
     * Scopes: conversations:update, ai_features.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/summarize_conversation_api_v1_conversations__conversation_id__summarize_post
