    }

    /**
     * Get Conversation Summary.
     *
     * Full AI ticket summary for a single conversation, broken into the three sections the
     * contact-page timeline renders on expand: user_intent, summary, resolution.
     *
     * Lazy-loaded by the FE when a ticket_summary timeline row is expanded — the timeline list
     * itself only carries a 140-char summary_preview to keep the list payload small. Reads the text
     * directly off the Conversation SHARD row (no KB-doc / RAG fetch).
     *
     * Returns 404 if the conversation does not exist in the caller's tenant (tenant-isolated — never
     * leaks cross-tenant ids). A conversation that exists but was never summarized (or was reopened,
     * which NULLs these fields) returns 200 with all three sections null.
     *
     * Scopes: knowledge_base:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/get_conversation_summary_api_v1_conversations__conversation_id__summary_get
     */
    public function getSummary(string $conversationId): ConversationSummaryDetail
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/conversations/'.Payload::segment($conversationId).'/summary',
        ));

        return ConversationSummaryDetail::fromArray($response->data());
    }

