     * conversation's current channel. Used by the frontend to render a channel picker before
     * generating deeplinks.
     *
     * Custom Inboxes security hardening (May 2026): for non-admin callers the list is intersected with
     * the channels reachable through the caller's accessible Custom Inboxes. Admins/owners and tenants
     * with zero inboxes are unaffected.
     *
     * Scopes: conversations:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/get_switchable_channels_api_v1_conversations__conversation_id__switchable_channels_get
     */
    public function getSwitchableChannels(string $conversationId): SwitchableChannels
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/conversations/'.Payload::segment($conversationId).'/switchable-channels',
        ));

        return SwitchableChannels::fromArray($response->data());
    }

    /**
     * Create Transcript Export.
     *
     * Start an async transcript export (PDF or ZIP) for a conversation.
     *
     * Creates a background job and returns it immediately with status queued (HTTP 202). Poll GET
     * /conversations/{conversation_id}/transcript/{job_id} until status is completed (a download_url
     * is then returned) or failed.
     *
     * Deduplication: a double-click / concurrent request is collapsed via a Redis SET NX EX lock, and
     * a reload / fresh-completed request reuses the existing job (an in-flight QUEUED/PROCESSING job,
     * or a COMPLETED one from the last few minutes) instead of enqueuing a duplicate.
     *
     * Scopes: conversations:read.
     *
     * @param  string  $format  Export artifact format: 'pdf' (transcript only) or 'zip' (transcript + attachments).
     * @param  ?bool  $waitForSummary  If true, the worker waits for the conversation's AI summary (``conversation.ai_summary``) to be populated before rendering, so the generated transcript can include the summary at the top. Defaults to false (render immediately). Does NOT affect export deduplication — a given (conversation, format) yields the same artifact regardless.
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/create_transcript_export_api_v1_conversations__conversation_id__transcript_post
     */
    public function createTranscriptExport(string $conversationId, string $format, ?bool $waitForSummary = null, ?string $idempotencyKey = null): TranscriptExportJob
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/conversations/'.Payload::segment($conversationId).'/transcript',
            body: Payload::body(['format' => $format, 'wait_for_summary' => $waitForSummary]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return TranscriptExportJob::fromArray($response->data());
    }

    /**
     * Get Transcript Export.
     *
     * Poll the status of an async transcript export job.
     *
     * When status is completed the response includes the download_url (and storage_path) written by
     * the worker; when failed see error_message.
     *
     * Scopes: conversations:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Conversations/get_transcript_export_api_v1_conversations__conversation_id__transcript__job_id__get
     */
    public function getTranscriptExport(string $conversationId, string $jobId): TranscriptExportJob
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/conversations/'.Payload::segment($conversationId).'/transcript/'.Payload::segment($jobId),
        ));

        return TranscriptExportJob::fromArray($response->data());
    }
}
